fn find_median(a: &[i32], b: &[i32]) -> i32 {
    assert_eq!(a.len(), b.len());
    let n = a.len();
    assert!(n > 0);

    if n % 2 == 1 {
        // Odd length: middle element of the first array.
        a[n / 2]
    } else {
        // Even length: average of:
        // - last element of the lower half of the first array: a[n/2 - 1]
        // - first element of the second array: b[0]
        //
        // Use i64 to avoid overflow when summing i32 values.
        let x = a[n / 2 - 1] as i64;
        let y = b[0] as i64;
        ((x + y) / 2) as i32
    }
}